le.","lanes":[{"id":"sdk","title":"Locale load","path":"shared_modules/nuc_languages/utils/fetch_locale_messages.ts","detail":"Fetch catalogs once.\nKeys stay aligned."},{"id":"data","title":"Translations","path":"shared_modules/nuc_languages/supabase/api/handle.ts","detail":"Copy lives in Supabase.\nSeeded per locale."},{"id":"ui","title":"Catalog","path":"shared_modules/nuc_languages/constants/languages.ts","detail":"Locales the picker shows.\nOne shared list."}]},{"id":"stores","name":"nuc_stores","icon":"mdi:database-outline","note":"Shared state. Shared verbs.","lanes":[{"id":"sdk","title":"Shared barrel","path":"shared_modules/nuc_stores/index.ts","detail":"Shared verbs.\nShared barrel."},{"id":"data","title":"Persist","path":"shared_modules/nuc_stores/cookie/set_item/index.ts","detail":"Cookie, local, session.\nOne set/get."},{"id":"ui","title":"Primitives","path":"shared_modules/nuc_stores/zustand/use_boolean_store.ts","detail":"Tiny building blocks.\nNo per-app rewrites."}]},{"id":"dark","name":"nuc_dark_mode","icon":"mdi:weather-night","note":"Load. Remember. Apply.","lanes":[{"id":"sdk","title":"useDarkMode","path":"shared_modules/nuc_dark_mode/utils/use_dark_mode.ts","detail":"Composable and hook.\nOne preference."},{"id":"data","title":"SSR lock","path":"shared_modules/nuc_dark_mode/plugins/dark_mode.server.ts","detail":"Locked before paint.\nNo theme flash."},{"id":"ui","title":"Apply","path":"shared_modules/nuc_dark_mode/utils/apply_dark_mode.ts","detail":"Class plus tokens.\nUI follows along."}]},{"id":"globals","name":"nuc_globals","icon":"mdi:earth","note":"Breakpoints, types, global SCSS.","lanes":[{"id":"sdk","title":"Media helpers","path":"shared_modules/nuc_globals/media/utils/is_mobile.ts","detail":"Shared helpers every shell already imports."},{"id":"data","title":"Register","path":"shared_modules/nuc_globals/nuc_globals.ts","detail":"Types, media, and globals - booted once."},{"id":"ui","title":"Global styles","path":"shared_modules/nuc_globals/styles/_index.scss","detail":"Shared SCSS DNA every shell speaks."}]}]}},{"id":"home-compiler","type":"section.compiler_demo","order":1,"props":{"railLabel":"Emit","anchorId":"compiler","showSection":true,"showBoard":true,"compilerEyebrow":"Code you would commit","compilerTitleLead":"Author once.","compilerTitleTrail":"Emit idioms.","compilerSupport":"Portable .nuc sources compile to React hooks, Vue composables, or Svelte runes - readable source you would actually merge. Domain and Supabase stay in shared_modules beside the UI.","compilerCta":"Read compiler docs","compilerHub":".nuc","compilerHubLabel":"author","compilerEmitLabel":"emit","sourceFile":"InboxBadge.nuc.tsx","sourceSnippet":"import { component, state, derived, handler }\n  from ''#nuc-compiler/runtime''\n\nexport default component({\n  name: ''InboxBadge'',\n  props: { inbox: { type: ''string'' } },\n  setup(props) {\n    const unread = state(3)\n    const label = derived(() =>\n      unread.value\n        ? `${props.inbox}: ${unread.value}`\n        : ''Caught up'')\n    const clear = handler(() => unread.set(0))\n    return () => (\n      <nui-button variant=\"filled\" onClick={clear}>\n        {label.value}\n      </nui-button>\n    )\n  },\n})","nodes":[{"id":"vue","label":"Vue","icon":"simple-icons:vuedotjs","color":"#42b883","command":"make web target=VUE","file":"InboxBadge.vue","snippet":"<script setup lang=\"ts\">\nimport { ref, computed } from ''vue''\n\nconst props = defineProps<{ inbox: string }>()\nconst unread = ref(3)\nconst label = computed(() =>\n  unread.value ? `${props.inbox}: ${unread.value}`\n    : ''Caught up'')\nfunction clear() { unread.value = 0 }\n</script>\n\n<template>\n  <nui-button variant=\"filled\" @click=\"clear\">\n    {{ label }}\n  </nui-button>\n</template>","x":26,"y":28},{"id":"react","label":"React","icon":"simple-icons:react","color":"#61dafb","command":"make web target=REACT","file":"InboxBadge.tsx","snippet":"''use client''\nimport { useState, useMemo, useCallback } from ''react''\n\ntype Props = { inbox: string }\n\nexport default function InboxBadge({ inbox }: Props) {\n  const [unread, setUnread] = useState(3)\n  const label = useMemo(\n    () => (unread ? `${inbox}: ${unread}` : ''Caught up''),\n    [unread, inbox])\n  const clear = useCallback(() => setUnread(0), [])\n  return (\n    <NuiButton variant=\"filled\" onClick={clear}>\n      {label}\n    </NuiButton>\n  )\n}","x":74,"y":28},{"id":"nuxt","label":"Nuxt","icon":"simple-icons:nuxtdotjs","color":"#00dc82","command":"make web target=NUXT","file":"InboxBadge.vue","snippet":"<script setup lang=\"ts\">\nconst props = defineProps<{ inbox: string }>()\nconst unread = useState(''inbox'', () => 3)\nconst label = computed(() =>\n  unread.value ? `${props.inbox}: ${unread.value}`\n    : ''Caught up'')\n</script>\n\n<template>\n  <nui-button variant=\"filled\" @click=\"unread = 0\">\n    {{ label }}\n  </nui-button>\n</template>","x":18,"y":52},{"id":"next","label":"Next","icon":"simple-icons:nextdotjs","color":"#e8e8e8","command":"make web target=NEXT","file":"InboxBadge.tsx","snippet":"''use client''\nimport { useState, useMemo } from ''react''\nimport { usePathname } from ''next/navigation''\n\ntype Props = { inbox: string }\n\nexport default function InboxBadge({ inbox }: Props) {\n  const path = usePathname()\n  const [unread, setUnread] = useState(3)\n  const label = useMemo(() =>\n    `${unread ? `${inbox}: ${unread}` : ''Caught up''} · ${path}`,\n    [unread, inbox, path])\n  return (\n    <NuiButton variant=\"filled\" onClick={() => setUnread(0)}>\n      {label}\n    </NuiButton>\n  )\n}","x":82,"y":52},{"id":"astro","label":"Astro","icon":"simple-icons:astro","color":"#ff5d01","command":"make web target=ASTRO","file":"InboxBadge.astro","snippet":"---\ninterface Props { inbox: string }\nconst { inbox } = Astro.props\n---\n\n<nui-button id=\"badge\" variant=\"filled\" data-inbox={inbox}>\n  {inbox}: 3\n</nui-button>\n\n<script is:inline>\n  const el = document.getElementById(''badge'')\n  let unread = 3\n  const paint = () => {\n    const box = el?.dataset.inbox ?? ''''\n    if (el) el.textContent = unread ? `${box}: ${unread}` : ''Caught up''\n  }\n  el?.addEventListener(\"click\", () => { unread = 0; paint() })\n</script>","x":34,"y":74},{"id":"svelte","label":"Svelte","icon":"simple-icons:svelte","color":"#ff3e00","command":"make web target=SVELTE","file":"InboxBadge.svelte","snippet":"<script lang=\"ts\">\n  type Props = { inbox: string }\n  let { inbox }: Props = $props()\n  let unread = $state(3)\n  let label = $derived(\n    unread ? `${inbox}: ${unread}` : ''Caught up'')\n</script>\n\n<nui-button variant=\"filled\" onclick={() => (unread = 0)}>\n  {label}\n</nui-button>","x":66,"y":74},{"id":"solid","label":"Solid","icon":"simple-icons:solid","color":"#72b7eb","command":"make web target=SOLID","file":"InboxBadge.tsx","snippet":"import { createSignal, createMemo } from ''solid-js''\n\ntype Props = { inbox: string }\n\nexport default function InboxBadge(props: Props) {\n  const [unread, setUnread] = createSignal(3)\n  const label = createMemo(() =>\n    unread() ? `${props.inbox}: ${unread()}`\n      : ''Caught up'')\n  return (\n    <nui-button variant=\"filled\" onClick={() => setUnread(0)}>\n      {label()}\n    </nui-button>\n  )\n}","x":50,"y":88}]}},{"id":"home-pillars","type":"section.pillars","order":2,"props":{"railLabel":"Ship","anchorId":"architecture","showSection":true,"showShareChart":true,"pillarsEyebrow":"What you actually ship","pillarsTitle":"One TypeScript nucleus. Framework shells are output.","pillarsSupport":"Write once in shared_modules and portable .nuc sources. Emit commit-ready UI for seven stacks, keep the same typed API client, and route every shell through one Supabase gateway.","pillarsCta":"Pick a shell","pillarsShareUnit":"emit targets","pillarsShareSource":"One IR surface. Seven framework shells.","items":[{"icon":"mdi:file-code-outline","index":"01","title":"Portable UI → idioma